INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-phrasal-b1-13-01', 'lesson-phrasal-b1-13', 1, 'phrasal', 'I work out three times a week.', 'Malho três vezes por semana.', '/aɪ wɜːrk aʊt θriː taɪmz ə wiːk/', '"Work out" (sem objeto) = fazer exercício, malhar.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"three","pos":"numeral","ipa":"/θriː/","gloss":"três"},{"surface":"times","pos":"noun","ipa":"/taɪmz/","gloss":"vezes"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"week","pos":"noun","ipa":"/wiːk/","gloss":"semana"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-13-02', 'lesson-phrasal-b1-13', 2, 'phrasal', 'Everything worked out in the end.', 'No fim, deu tudo certo.', '/ˈɛvriθɪŋ wɜːrkt aʊt ɪn ðə ɛnd/', '"Work out" = dar certo, resolver-se.', '[]'::jsonb, '[{"surface":"Everything","pos":"pronoun","ipa":"/ˈɛvriθɪŋ/","gloss":"tudo"},{"surface":"worked","pos":"verb","ipa":"/wɜːrkt/","gloss":"trabalhou"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"end","pos":"noun","ipa":"/ɛnd/","gloss":"fim, final"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-13-03', 'lesson-phrasal-b1-13', 3, 'phrasal', 'I can''t work out the answer.', 'Não consigo descobrir a resposta.', '/aɪ kænt wɜːrk aʊt ðə ˈænsər/', '"Work out" + objeto = descobrir, calcular. Separável: "work it out".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"can''t","pos":"auxiliary verb","ipa":"/kænt/","gloss":"não poder"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"answer","pos":"noun","ipa":"/ˈænsər/","gloss":"resposta"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-13-04', 'lesson-phrasal-b1-13', 4, 'phrasal', 'We''ll work it out together.', 'Vamos resolver isso juntos.', '/wiːl wɜːrk ɪt aʊt təˈɡɛðər/', 'Com pronome, o objeto vai no meio: "work it out".', '[]'::jsonb, '[{"surface":"We''ll","pos":"pronoun","ipa":"/wiːl/","gloss":"nós vamos (we will)"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"together","pos":"adverb","ipa":"/təˈɡɛðər/","gloss":"juntos"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-13-05', 'lesson-phrasal-b1-13', 5, 'phrasal', 'I''m working on a new project.', 'Estou trabalhando num projeto novo.', '/aɪm ˈwɜːrkɪŋ ɑːn ə nuː ˈprɑːdʒɛkt/', '"Work on" = dedicar-se a algo. Não separável.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"working","pos":"verb","ipa":"/ˈwɜːrkɪŋ/","gloss":"funcionando; trabalhando"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"new","pos":"adjective","ipa":"/nuː/","gloss":"novo"},{"surface":"project","pos":"noun","ipa":"/ˈprɑːdʒɛkt/","gloss":"projeto"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-13-06', 'lesson-phrasal-b1-13', 6, 'phrasal', 'She needs to work on her pronunciation.', 'Ela precisa melhorar a pronúncia.', '/ʃiː niːdz tuː wɜːrk ɑːn hɜːr prəˌnʌnsiˈeɪʃən/', '"Work on" também = praticar para melhorar.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"needs","pos":"verb","ipa":"/niːdz/","gloss":"precisa"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"pronunciation","pos":"noun","ipa":"/prəˌnʌnsiˈeɪʃən/","gloss":"pronúncia"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-13-07', 'lesson-phrasal-b1-13', 7, 'phrasal', 'Don''t get worked up about it.', 'Não fique nervoso com isso.', '/doʊnt ɡɛt wɜːrkt ʌp əˈbaʊt ɪt/', '"Get worked up" = ficar agitado, nervoso.', '[]'::jsonb, '[{"surface":"Don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"worked","pos":"verb","ipa":"/wɜːrkt/","gloss":"trabalhou"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-13-08', 'lesson-phrasal-b1-13', 8, 'phrasal', 'He worked his way up to manager.', 'Ele foi subindo até virar gerente.', '/hiː wɜːrkt hɪz weɪ ʌp tuː ˈmænɪdʒər/', '"Work your way up" = subir aos poucos, por esforço.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"worked","pos":"verb","ipa":"/wɜːrkt/","gloss":"trabalhou"},{"surface":"his","pos":"determiner","ipa":"/hɪz/","gloss":"dele"},{"surface":"way","pos":"noun","ipa":"/weɪ/","gloss":"caminho; jeito"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"manager","pos":"noun","ipa":"/ˈmænɪdʒər/","gloss":"gerente"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-13-09', 'lesson-phrasal-b1-13', 9, 'phrasal', 'The plan did not work out.', 'O plano não deu certo.', '/ðə plæn dɪd nɑːt wɜːrk aʊt/', 'Negativa de "work out" = não funcionar.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"plan","pos":"noun","ipa":"/plæn/","gloss":"plano"},{"surface":"did","pos":"verb","ipa":"/dɪd/","gloss":"fez"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-13-10', 'lesson-phrasal-b1-13', 10, 'phrasal', 'It works out cheaper by train.', 'Sai mais barato de trem.', '/ɪt wɜːrks aʊt ˈtʃiːpər baɪ treɪn/', '"Work out" + adjetivo = sair (custo final).', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"works","pos":"verb","ipa":"/wɜːrks/","gloss":"funciona, serve"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"cheaper","pos":"adjective","ipa":"/ˈtʃiːpər/","gloss":"mais barato"},{"surface":"by","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"train","pos":"noun","ipa":"/treɪn/","gloss":"trem"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-phrasal-b1-14-01', 'lesson-phrasal-b1-14', 1, 'phrasal', 'Please fill in this form.', 'Por favor, preencha este formulário.', '/pliːz fɪl ɪn ðɪs fɔːrm/', '"Fill in" = preencher (britânico). Separável.', '[]'::jsonb, '[{"surface":"Please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"},{"surface":"fill","pos":"verb","ipa":"/fɪl/","gloss":"preencher; obturar"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"form","pos":"noun","ipa":"/fɔːrm/","gloss":"formulário"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-14-02', 'lesson-phrasal-b1-14', 2, 'phrasal', 'Fill out the application online.', 'Preencha a inscrição online.', '/fɪl aʊt ðə ˌæplɪˈkeɪʃən ˌɑːnˈlaɪn/', '"Fill out" = preencher (americano).', '[]'::jsonb, '[{"surface":"Fill","pos":"verb","ipa":"/fɪl/","gloss":"preencher; obturar"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"application","pos":"noun","ipa":"/ˌæplɪˈkeɪʃən/","gloss":"inscrição, candidatura"},{"surface":"online","pos":"adverb","ipa":"/ˌɑːnˈlaɪn/","gloss":"na internet"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-14-03', 'lesson-phrasal-b1-14', 3, 'phrasal', 'Fill in the blanks.', 'Complete as lacunas.', '/fɪl ɪn ðə blæŋks/', 'Instrução clássica de exercício.', '[]'::jsonb, '[{"surface":"Fill","pos":"verb","ipa":"/fɪl/","gloss":"preencher; obturar"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"blanks","pos":"noun","ipa":"/blæŋks/","gloss":"lacunas"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-14-04', 'lesson-phrasal-b1-14', 4, 'phrasal', 'Can you fill me in on the meeting?', 'Pode me atualizar sobre a reunião?', '/kæn juː fɪl miː ɪn ɑːn ðə ˈmiːtɪŋ/', '"Fill someone in" = pôr alguém a par.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"fill","pos":"verb","ipa":"/fɪl/","gloss":"preencher; obturar"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"meeting","pos":"noun","ipa":"/ˈmiːtɪŋ/","gloss":"reunião"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-14-05', 'lesson-phrasal-b1-14', 5, 'phrasal', 'She filled in for me yesterday.', 'Ela me substituiu ontem.', '/ʃiː fɪld ɪn fɔːr miː ˈjɛstərdeɪ/', '"Fill in for" = cobrir alguém no trabalho.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"filled","pos":"verb","ipa":"/fɪld/","gloss":"encheu, preencheu"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"yesterday","pos":"adverb","ipa":"/ˈjɛstərdeɪ/","gloss":"ontem"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-14-06', 'lesson-phrasal-b1-14', 6, 'phrasal', 'I need to fill up the tank.', 'Preciso encher o tanque.', '/aɪ niːd tuː fɪl ʌp ðə tæŋk/', '"Fill up" = encher completamente.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"fill","pos":"verb","ipa":"/fɪl/","gloss":"preencher; obturar"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"tank","pos":"noun","ipa":"/tæŋk/","gloss":"tanque"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-14-07', 'lesson-phrasal-b1-14', 7, 'phrasal', 'Fill it up, please.', 'Enche, por favor.', '/fɪl ɪt ʌp pliːz/', 'No posto: "fill it up" = completa o tanque.', '[]'::jsonb, '[{"surface":"Fill","pos":"verb","ipa":"/fɪl/","gloss":"preencher; obturar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-14-08', 'lesson-phrasal-b1-14', 8, 'phrasal', 'Don''t fill up on bread.', 'Não se encha de pão.', '/doʊnt fɪl ʌp ɑːn brɛd/', '"Fill up on" = encher-se de alguma comida.', '[]'::jsonb, '[{"surface":"Don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"fill","pos":"verb","ipa":"/fɪl/","gloss":"preencher; obturar"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"bread","pos":"noun","ipa":"/brɛd/","gloss":"pão"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-14-09', 'lesson-phrasal-b1-14', 9, 'phrasal', 'The room filled up quickly.', 'A sala lotou rápido.', '/ðə ruːm fɪld ʌp ˈkwɪkli/', 'Sem objeto: "fill up" = lotar.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"room","pos":"noun","ipa":"/ruːm/","gloss":"quarto"},{"surface":"filled","pos":"verb","ipa":"/fɪld/","gloss":"encheu, preencheu"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"quickly","pos":"adverb","ipa":"/ˈkwɪkli/","gloss":"rapidamente"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-14-10', 'lesson-phrasal-b1-14', 10, 'phrasal', 'I''m filled up, thanks.', 'Estou satisfeito, obrigado.', '/aɪm fɪld ʌp θæŋks/', 'Informal para "estou cheio".', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"filled","pos":"verb","ipa":"/fɪld/","gloss":"encheu, preencheu"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"thanks","pos":"interjection","ipa":"/θæŋks/","gloss":"obrigado, valeu"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-phrasal-b1-15-01', 'lesson-phrasal-b1-15', 1, 'phrasal', 'We checked in at the hotel at noon.', 'Fizemos check-in no hotel ao meio-dia.', '/wiː tʃɛkt ɪn æt ðə hoʊˈtɛl æt nuːn/', '"Check in" = registrar-se na chegada.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"checked","pos":"verb","ipa":"/tʃɛkt/","gloss":"verificou, marcou"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"hotel","pos":"noun","ipa":"/hoʊˈtɛl/","gloss":"hotel"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"noon","pos":"noun","ipa":"/nuːn/","gloss":"meio-dia"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-15-02', 'lesson-phrasal-b1-15', 2, 'phrasal', 'What time do we have to check out?', 'A que horas temos que fazer check-out?', '/wʌt taɪm duː wiː hæv tuː tʃɛk aʊt/', '"Check out" = sair e pagar no hotel.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"check","pos":"verb","ipa":"/tʃɛk/","gloss":"fazer (check-in)"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-15-03', 'lesson-phrasal-b1-15', 3, 'phrasal', 'Check out this video!', 'Olha este vídeo!', '/tʃɛk aʊt ðɪs ˈvɪdioʊ/', '"Check out" informal = dar uma olhada.', '[]'::jsonb, '[{"surface":"Check","pos":"verb","ipa":"/tʃɛk/","gloss":"fazer (check-in)"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"video","pos":"noun","ipa":"/ˈvɪdioʊ/","gloss":"vídeo"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-15-04', 'lesson-phrasal-b1-15', 4, 'phrasal', 'Let me check out the menu first.', 'Deixa eu dar uma olhada no cardápio primeiro.', '/lɛt miː tʃɛk aʊt ðə ˈmɛnjuː fɜːrst/', 'Separável: "check it out".', '[]'::jsonb, '[{"surface":"Let","pos":"verb","ipa":"/lɛt/","gloss":"deixar, permitir"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"check","pos":"verb","ipa":"/tʃɛk/","gloss":"fazer (check-in)"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"menu","pos":"noun","ipa":"/ˈmɛnjuː/","gloss":"cardápio"},{"surface":"first","pos":"adjective","ipa":"/fɜːrst/","gloss":"primeiro"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-15-05', 'lesson-phrasal-b1-15', 5, 'phrasal', 'Can you check on the kids?', 'Pode dar uma olhada nas crianças?', '/kæn juː tʃɛk ɑːn ðə kɪdz/', '"Check on" = verificar se está tudo bem.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"check","pos":"verb","ipa":"/tʃɛk/","gloss":"fazer (check-in)"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"kids","pos":"noun","ipa":"/kɪdz/","gloss":"crianças, filhos"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-15-06', 'lesson-phrasal-b1-15', 6, 'phrasal', 'I''ll check with my boss.', 'Vou confirmar com meu chefe.', '/aɪl tʃɛk wɪð maɪ bɔːs/', '"Check with" = consultar alguém.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"check","pos":"verb","ipa":"/tʃɛk/","gloss":"fazer (check-in)"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"boss","pos":"noun","ipa":"/bɔːs/","gloss":"chefe"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-15-07', 'lesson-phrasal-b1-15', 7, 'phrasal', 'Please check over your answers.', 'Por favor, revise suas respostas.', '/pliːz tʃɛk ˈoʊvər jʊr ˈænsərz/', '"Check over" = revisar com atenção.', '[]'::jsonb, '[{"surface":"Please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"},{"surface":"check","pos":"verb","ipa":"/tʃɛk/","gloss":"fazer (check-in)"},{"surface":"over","pos":"preposition","ipa":"/ˈoʊvər/","gloss":"por cima; superado"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"answers","pos":"noun","ipa":"/ˈænsərz/","gloss":"respostas"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-15-08', 'lesson-phrasal-b1-15', 8, 'phrasal', 'I just wanted to check in.', 'Só queria saber como você está.', '/aɪ dʒʌst ˈwɑːntɪd tuː tʃɛk ɪn/', '"Check in" com alguém = dar notícias, saber como está.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"just","pos":"adverb","ipa":"/dʒʌst/","gloss":"só, apenas"},{"surface":"wanted","pos":"verb","ipa":"/ˈwɑːntɪd/","gloss":"quis, queria"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"check","pos":"verb","ipa":"/tʃɛk/","gloss":"fazer (check-in)"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-15-09', 'lesson-phrasal-b1-15', 9, 'phrasal', 'She checked off every item on the list.', 'Ela marcou cada item da lista.', '/ʃiː tʃɛkt ɔːf ˈɛvri ˈaɪtəm ɑːn ðə lɪst/', '"Check off" = riscar da lista.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"checked","pos":"verb","ipa":"/tʃɛkt/","gloss":"verificou, marcou"},{"surface":"off","pos":"particle","ipa":"/ɔːf/","gloss":"(partícula: off)"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"item","pos":"noun","ipa":"/ˈaɪtəm/","gloss":"item"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"list","pos":"noun","ipa":"/lɪst/","gloss":"lista"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-15-10', 'lesson-phrasal-b1-15', 10, 'phrasal', 'Did you check the facts?', 'Você verificou os fatos?', '/dɪd juː tʃɛk ðə fækts/', 'Sem partícula: "check" = verificar. Compare com os phrasals.', '[]'::jsonb, '[{"surface":"Did","pos":"verb","ipa":"/dɪd/","gloss":"fez"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"check","pos":"verb","ipa":"/tʃɛk/","gloss":"fazer (check-in)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"facts","pos":"noun","ipa":"/fækts/","gloss":"fatos"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-phrasal-b1-16-01', 'lesson-phrasal-b1-16', 1, 'phrasal', 'We hang out every Friday.', 'A gente sai junto toda sexta.', '/wiː hæŋ aʊt ˈɛvri ˈfraɪdeɪ/', '"Hang out" = passar tempo junto, sair.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"hang","pos":"verb","ipa":"/hæŋ/","gloss":"pendurar"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"Friday","pos":"proper noun","ipa":"/ˈfraɪdeɪ/","gloss":"sexta-feira"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-16-02', 'lesson-phrasal-b1-16', 2, 'phrasal', 'Don''t hang up!', 'Não desliga!', '/doʊnt hæŋ ʌp/', '"Hang up" = desligar o telefone.', '[]'::jsonb, '[{"surface":"Don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"hang","pos":"verb","ipa":"/hæŋ/","gloss":"pendurar"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-16-03', 'lesson-phrasal-b1-16', 3, 'phrasal', 'He hung up on me.', 'Ele desligou na minha cara.', '/hiː hʌŋ ʌp ɑːn miː/', '"Hang up on someone" = desligar na cara.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"hung","pos":"verb","ipa":"/hʌŋ/","gloss":"pendurou; desligou"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-16-04', 'lesson-phrasal-b1-16', 4, 'phrasal', 'Hang on a second.', 'Espera um segundo.', '/hæŋ ɑːn ə ˈsɛkənd/', '"Hang on" = esperar (informal).', '[]'::jsonb, '[{"surface":"Hang","pos":"verb","ipa":"/hæŋ/","gloss":"pendurar"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"second","pos":"adjective","ipa":"/ˈsɛkənd/","gloss":"segundo"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-16-05', 'lesson-phrasal-b1-16', 5, 'phrasal', 'Hang on tight!', 'Segura firme!', '/hæŋ ɑːn taɪt/', '"Hang on" também = segurar firme.', '[]'::jsonb, '[{"surface":"Hang","pos":"verb","ipa":"/hæŋ/","gloss":"pendurar"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"tight","pos":"adjective","ipa":"/taɪt/","gloss":"apertado"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-16-06', 'lesson-phrasal-b1-16', 6, 'phrasal', 'Hang up your coat here.', 'Pendure seu casaco aqui.', '/hæŋ ʌp jʊr koʊt hɪr/', '"Hang up" + roupa = pendurar. Separável.', '[]'::jsonb, '[{"surface":"Hang","pos":"verb","ipa":"/hæŋ/","gloss":"pendurar"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"coat","pos":"noun","ipa":"/koʊt/","gloss":"casaco"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-16-07', 'lesson-phrasal-b1-16', 7, 'phrasal', 'Just hang in there.', 'Aguenta firme.', '/dʒʌst hæŋ ɪn ðɛr/', '"Hang in there" = não desista.', '[]'::jsonb, '[{"surface":"Just","pos":"adverb","ipa":"/dʒʌst/","gloss":"só, apenas"},{"surface":"hang","pos":"verb","ipa":"/hæŋ/","gloss":"pendurar"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-16-08', 'lesson-phrasal-b1-16', 8, 'phrasal', 'Where do you usually hang out?', 'Onde você costuma sair?', '/wɛr duː juː ˈjuːʒuəli hæŋ aʊt/', 'Pergunta comum para conhecer alguém.', '[]'::jsonb, '[{"surface":"Where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"usually","pos":"adverb","ipa":"/ˈjuːʒuəli/","gloss":"geralmente"},{"surface":"hang","pos":"verb","ipa":"/hæŋ/","gloss":"pendurar"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-16-09', 'lesson-phrasal-b1-16', 9, 'phrasal', 'I hung around for an hour.', 'Fiquei por ali uma hora.', '/aɪ hʌŋ əˈraʊnd fɔːr ən ˈaʊər/', '"Hang around" = ficar à toa num lugar.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"hung","pos":"verb","ipa":"/hʌŋ/","gloss":"pendurou; desligou"},{"surface":"around","pos":"adverb","ipa":"/əˈraʊnd/","gloss":"ao redor, por"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"hour","pos":"noun","ipa":"/ˈaʊər/","gloss":"hora"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-16-10', 'lesson-phrasal-b1-16', 10, 'phrasal', 'She''s hung up on her ex.', 'Ela ainda está presa ao ex.', '/ʃiːz hʌŋ ʌp ɑːn hɜːr ɛks/', '"Hung up on" (adjetivo) = obcecado, preso emocionalmente.', '[]'::jsonb, '[{"surface":"She''s","pos":"pronoun","ipa":"/ʃiːz/","gloss":"ela é, ela está"},{"surface":"hung","pos":"verb","ipa":"/hʌŋ/","gloss":"pendurou; desligou"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"ex","pos":"noun","ipa":"/ɛks/","gloss":"ex (namorado ou namorada)"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-phrasal-b1-17-01', 'lesson-phrasal-b1-17', 1, 'phrasal', 'Hold on, I will check.', 'Espera, vou verificar.', '/hoʊld ɑːn aɪ wɪl tʃɛk/', '"Hold on" = esperar, como "hang on".', '[]'::jsonb, '[{"surface":"Hold","pos":"verb","ipa":"/hoʊld/","gloss":"aguardar (na linha), segurar"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"check","pos":"verb","ipa":"/tʃɛk/","gloss":"fazer (check-in)"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-17-02', 'lesson-phrasal-b1-17', 2, 'phrasal', 'Sorry, I got held up in traffic.', 'Desculpe, fiquei preso no trânsito.', '/ˈsɑːri aɪ ɡɑːt hɛld ʌp ɪn ˈtræfɪk/', '"Held up" = atrasado.', '[]'::jsonb, '[{"surface":"Sorry","pos":"adjective","ipa":"/ˈsɑːri/","gloss":"desculpa"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"got","pos":"verb","ipa":"/ɡɑːt/","gloss":"conseguiu, pegou"},{"surface":"held","pos":"verb","ipa":"/hɛld/","gloss":"segurou, realizou"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"traffic","pos":"noun","ipa":"/ˈtræfɪk/","gloss":"trânsito"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-17-03', 'lesson-phrasal-b1-17', 3, 'phrasal', 'Hold up, that''s not right.', 'Pera aí, isso não está certo.', '/hoʊld ʌp ðæts nɑːt raɪt/', '"Hold up" informal = espera aí.', '[]'::jsonb, '[{"surface":"Hold","pos":"verb","ipa":"/hoʊld/","gloss":"aguardar (na linha), segurar"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"that''s","pos":"pronoun","ipa":"/ðæts/","gloss":"isso é"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"right","pos":"adverb","ipa":"/raɪt/","gloss":"bem; né? (right?)"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-17-04', 'lesson-phrasal-b1-17', 4, 'phrasal', 'Don''t hold back, tell me.', 'Não se segura, me conta.', '/doʊnt hoʊld bæk tɛl miː/', '"Hold back" = conter-se.', '[]'::jsonb, '[{"surface":"Don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"hold","pos":"verb","ipa":"/hoʊld/","gloss":"aguardar (na linha), segurar"},{"surface":"back","pos":"adverb","ipa":"/bæk/","gloss":"de volta"},{"surface":"tell","pos":"verb","ipa":"/tɛl/","gloss":"contar, dizer"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-17-05', 'lesson-phrasal-b1-17', 5, 'phrasal', 'She held back her tears.', 'Ela segurou as lágrimas.', '/ʃiː hɛld bæk hɜːr tɪrz/', 'Separável: "held her tears back".', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"held","pos":"verb","ipa":"/hɛld/","gloss":"segurou, realizou"},{"surface":"back","pos":"adverb","ipa":"/bæk/","gloss":"de volta"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"tears","pos":"noun","ipa":"/tɪrz/","gloss":"lágrimas"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-17-06', 'lesson-phrasal-b1-17', 6, 'phrasal', 'Hold onto your ticket.', 'Guarde seu ingresso.', '/hoʊld ˈɑːntuː jʊr ˈtɪkɪt/', '"Hold onto" = guardar, não soltar.', '[]'::jsonb, '[{"surface":"Hold","pos":"verb","ipa":"/hoʊld/","gloss":"aguardar (na linha), segurar"},{"surface":"onto","pos":"preposition","ipa":"/ˈɑːntuː/","gloss":"em, sobre"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"ticket","pos":"noun","ipa":"/ˈtɪkɪt/","gloss":"passagem, bilhete"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-17-07', 'lesson-phrasal-b1-17', 7, 'phrasal', 'How are you holding up?', 'Como você está aguentando?', '/haʊ ɑːr juː ˈhoʊldɪŋ ʌp/', '"Hold up" = aguentar uma fase difícil.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"holding","pos":"verb","ipa":"/ˈhoʊldɪŋ/","gloss":"segurando"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-17-08', 'lesson-phrasal-b1-17', 8, 'phrasal', 'The bank was held up yesterday.', 'O banco foi assaltado ontem.', '/ðə bæŋk wɑːz hɛld ʌp ˈjɛstərdeɪ/', '"Hold up" + lugar = assaltar à mão armada.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bank","pos":"noun","ipa":"/bæŋk/","gloss":"banco"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"held","pos":"verb","ipa":"/hɛld/","gloss":"segurou, realizou"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"yesterday","pos":"adverb","ipa":"/ˈjɛstərdeɪ/","gloss":"ontem"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-17-09', 'lesson-phrasal-b1-17', 9, 'phrasal', 'Can you hold off until Monday?', 'Pode esperar até segunda?', '/kæn juː hoʊld ɔːf ənˈtɪl ˈmʌndeɪ/', '"Hold off" = adiar.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"hold","pos":"verb","ipa":"/hoʊld/","gloss":"aguardar (na linha), segurar"},{"surface":"off","pos":"particle","ipa":"/ɔːf/","gloss":"(partícula: off)"},{"surface":"until","pos":"conjunction","ipa":"/ənˈtɪl/","gloss":"até"},{"surface":"Monday","pos":"proper noun","ipa":"/ˈmʌndeɪ/","gloss":"segunda-feira"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-17-10', 'lesson-phrasal-b1-17', 10, 'phrasal', 'Hold it right there!', 'Pare aí mesmo!', '/hoʊld ɪt raɪt ðɛr/', 'Ordem para parar.', '[]'::jsonb, '[{"surface":"Hold","pos":"verb","ipa":"/hoʊld/","gloss":"aguardar (na linha), segurar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"right","pos":"adverb","ipa":"/raɪt/","gloss":"bem; né? (right?)"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-phrasal-b1-18-01', 'lesson-phrasal-b1-18', 1, 'phrasal', 'Keep up the good work!', 'Continue com o bom trabalho!', '/kiːp ʌp ðə ɡʊd wɜːrk/', '"Keep up" = manter o nível.', '[]'::jsonb, '[{"surface":"Keep","pos":"verb","ipa":"/kiːp/","gloss":"manter"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"good","pos":"adjective","ipa":"/ɡʊd/","gloss":"bom"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-18-02', 'lesson-phrasal-b1-18', 2, 'phrasal', 'I can''t keep up with you.', 'Não consigo te acompanhar.', '/aɪ kænt kiːp ʌp wɪð juː/', '"Keep up with" = acompanhar o ritmo.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"can''t","pos":"auxiliary verb","ipa":"/kænt/","gloss":"não poder"},{"surface":"keep","pos":"verb","ipa":"/kiːp/","gloss":"manter"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-18-03', 'lesson-phrasal-b1-18', 3, 'phrasal', 'He keeps on talking.', 'Ele não para de falar.', '/hiː kiːps ɑːn ˈtɔːkɪŋ/', '"Keep on" + -ing = continuar insistindo.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"keeps","pos":"verb","ipa":"/kiːps/","gloss":"mantém"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"talking","pos":"verb","ipa":"/ˈtɔːkɪŋ/","gloss":"conversar"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-18-04', 'lesson-phrasal-b1-18', 4, 'phrasal', 'Keep away from the edge.', 'Fique longe da beirada.', '/kiːp əˈweɪ frʌm ðə ɛdʒ/', '"Keep away from" = manter distância.', '[]'::jsonb, '[{"surface":"Keep","pos":"verb","ipa":"/kiːp/","gloss":"manter"},{"surface":"away","pos":"adverb","ipa":"/əˈweɪ/","gloss":"embora; (right away) já"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"edge","pos":"noun","ipa":"/ɛdʒ/","gloss":"beirada"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-18-05', 'lesson-phrasal-b1-18', 5, 'phrasal', 'Keep the noise down, please.', 'Façam menos barulho, por favor.', '/kiːp ðə nɔɪz daʊn pliːz/', '"Keep down" = manter baixo. Separável.', '[]'::jsonb, '[{"surface":"Keep","pos":"verb","ipa":"/kiːp/","gloss":"manter"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"noise","pos":"noun","ipa":"/nɔɪz/","gloss":"barulho"},{"surface":"down","pos":"adjective","ipa":"/daʊn/","gloss":"dentro, topando (gíria)"},{"surface":"please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-18-06', 'lesson-phrasal-b1-18', 6, 'phrasal', 'Keep it up!', 'Continue assim!', '/kiːp ɪt ʌp/', 'Incentivo curto.', '[]'::jsonb, '[{"surface":"Keep","pos":"verb","ipa":"/kiːp/","gloss":"manter"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-18-07', 'lesson-phrasal-b1-18', 7, 'phrasal', 'I try to keep up with the news.', 'Tento me manter atualizado com as notícias.', '/aɪ traɪ tuː kiːp ʌp wɪð ðə nuːz/', '"Keep up with" = manter-se informado.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"try","pos":"verb","ipa":"/traɪ/","gloss":"experimentar, tentar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"keep","pos":"verb","ipa":"/kiːp/","gloss":"manter"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"news","pos":"noun","ipa":"/nuːz/","gloss":"notícia(s)"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-18-08', 'lesson-phrasal-b1-18', 8, 'phrasal', 'Keep off the grass.', 'Não pise na grama.', '/kiːp ɔːf ðə ɡræs/', 'Placa comum: "keep off" = não entrar, não tocar.', '[]'::jsonb, '[{"surface":"Keep","pos":"verb","ipa":"/kiːp/","gloss":"manter"},{"surface":"off","pos":"particle","ipa":"/ɔːf/","gloss":"(partícula: off)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"grass","pos":"noun","ipa":"/ɡræs/","gloss":"grama"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-18-09', 'lesson-phrasal-b1-18', 9, 'phrasal', 'She kept me waiting for an hour.', 'Ela me deixou esperando uma hora.', '/ʃiː kɛpt miː ˈweɪtɪŋ fɔːr ən ˈaʊər/', '"Keep someone waiting" = deixar esperando.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"kept","pos":"verb","ipa":"/kɛpt/","gloss":"guardou, manteve"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"waiting","pos":"verb","ipa":"/ˈweɪtɪŋ/","gloss":"esperando"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"hour","pos":"noun","ipa":"/ˈaʊər/","gloss":"hora"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-18-10', 'lesson-phrasal-b1-18', 10, 'phrasal', 'Keep it to yourself.', 'Guarde isso para você.', '/kiːp ɪt tuː jərˈsɛlf/', '"Keep to yourself" = não contar.', '[]'::jsonb, '[{"surface":"Keep","pos":"verb","ipa":"/kiːp/","gloss":"manter"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"yourself","pos":"pronoun","ipa":"/jərˈsɛlf/","gloss":"você mesmo"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-phrasal-b1-19-01', 'lesson-phrasal-b1-19', 1, 'phrasal', 'I wake up at six.', 'Acordo às seis.', '/aɪ weɪk ʌp æt sɪks/', '"Wake up" = acordar.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"wake","pos":"verb","ipa":"/weɪk/","gloss":"acordar"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"six","pos":"numeral","ipa":"/sɪks/","gloss":"seis"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-19-02', 'lesson-phrasal-b1-19', 2, 'phrasal', 'I get up right away.', 'Me levanto na hora.', '/aɪ ɡɛt ʌp raɪt əˈweɪ/', '"Get up" = levantar da cama.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"right","pos":"adverb","ipa":"/raɪt/","gloss":"bem; né? (right?)"},{"surface":"away","pos":"adverb","ipa":"/əˈweɪ/","gloss":"embora; (right away) já"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-19-03', 'lesson-phrasal-b1-19', 3, 'phrasal', 'Can you clean up the kitchen?', 'Pode limpar a cozinha?', '/kæn juː kliːn ʌp ðə ˈkɪtʃən/', '"Clean up" = arrumar, limpar tudo.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"clean","pos":"verb","ipa":"/kliːn/","gloss":"limpar"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"kitchen","pos":"noun","ipa":"/ˈkɪtʃən/","gloss":"cozinha"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-19-04', 'lesson-phrasal-b1-19', 4, 'phrasal', 'Take out the trash, please.', 'Leve o lixo para fora, por favor.', '/teɪk aʊt ðə træʃ pliːz/', '"Take out" = levar para fora. Separável.', '[]'::jsonb, '[{"surface":"Take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"trash","pos":"noun","ipa":"/træʃ/","gloss":"lixo"},{"surface":"please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-19-05', 'lesson-phrasal-b1-19', 5, 'phrasal', 'I need to wash up.', 'Preciso lavar a louça.', '/aɪ niːd tuː wɑːʃ ʌp/', '"Wash up" = lavar a louça (britânico); lavar-se (americano).', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"wash","pos":"verb","ipa":"/wɑːʃ/","gloss":"lavar"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-19-06', 'lesson-phrasal-b1-19', 6, 'phrasal', 'Plug in the charger.', 'Coloque o carregador na tomada.', '/plʌɡ ɪn ðə ˈtʃɑːrdʒər/', '"Plug in" = ligar na tomada.', '[]'::jsonb, '[{"surface":"Plug","pos":"verb","ipa":"/plʌɡ/","gloss":"ligar na tomada"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"charger","pos":"noun","ipa":"/ˈtʃɑːrdʒər/","gloss":"carregador"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-19-07', 'lesson-phrasal-b1-19', 7, 'phrasal', 'I ran out of milk.', 'Acabou o leite.', '/aɪ ræn aʊt ʌv mɪlk/', '"Run out of" = ficar sem.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"ran","pos":"verb","ipa":"/ræn/","gloss":"correu"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"milk","pos":"noun","ipa":"/mɪlk/","gloss":"leite"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-19-08', 'lesson-phrasal-b1-19', 8, 'phrasal', 'Put away your clothes.', 'Guarde suas roupas.', '/pʊt əˈweɪ jʊr kloʊðz/', '"Put away" = guardar no lugar.', '[]'::jsonb, '[{"surface":"Put","pos":"verb","ipa":"/pʊt/","gloss":"colocar"},{"surface":"away","pos":"adverb","ipa":"/əˈweɪ/","gloss":"embora; (right away) já"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"clothes","pos":"noun","ipa":"/kloʊðz/","gloss":"roupas"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-19-09', 'lesson-phrasal-b1-19', 9, 'phrasal', 'I dozed off on the sofa.', 'Cochilei no sofá.', '/aɪ doʊzd ɔːf ɑːn ðə ˈsoʊfə/', '"Doze off" = pegar no sono sem querer.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"dozed","pos":"verb","ipa":"/doʊzd/","gloss":"cochilou"},{"surface":"off","pos":"particle","ipa":"/ɔːf/","gloss":"(partícula: off)"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"sofa","pos":"noun","ipa":"/ˈsoʊfə/","gloss":"sofá"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-19-10', 'lesson-phrasal-b1-19', 10, 'phrasal', 'Can you pick up some bread?', 'Pode comprar pão?', '/kæn juː pɪk ʌp sʌm brɛd/', '"Pick up" = buscar, comprar de passagem.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"pick","pos":"verb","ipa":"/pɪk/","gloss":"pegar (pick up)"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"bread","pos":"noun","ipa":"/brɛd/","gloss":"pão"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-phrasal-b1-20-01', 'lesson-phrasal-b1-20', 1, 'phrasal', 'We get along really well.', 'A gente se dá muito bem.', '/wiː ɡɛt əˈlɔːŋ ˈriːəli wɛl/', '"Get along" = dar-se bem.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"along","pos":"particle","ipa":"/əˈlɔːŋ/","gloss":"junto (get along = dar-se bem)"},{"surface":"really","pos":"adverb","ipa":"/ˈriːəli/","gloss":"muito, de verdade"},{"surface":"well","pos":"adverb","ipa":"/wɛl/","gloss":"bem"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-20-02', 'lesson-phrasal-b1-20', 2, 'phrasal', 'They broke up last year.', 'Eles terminaram ano passado.', '/ðeɪ broʊk ʌp læst jɪr/', '"Break up" = terminar um relacionamento.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"broke","pos":"verb","ipa":"/broʊk/","gloss":"quebrou"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"year","pos":"noun","ipa":"/jɪr/","gloss":"ano"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-20-03', 'lesson-phrasal-b1-20', 3, 'phrasal', 'He asked her out.', 'Ele a chamou para sair.', '/hiː æskt hɜːr aʊt/', '"Ask out" = convidar para um encontro. Separável.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"asked","pos":"verb","ipa":"/æskt/","gloss":"perguntou, pediu"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-20-04', 'lesson-phrasal-b1-20', 4, 'phrasal', 'I fell out with my cousin.', 'Briguei com meu primo.', '/aɪ fɛl aʊt wɪð maɪ ˈkʌzən/', '"Fall out with" = brigar e se afastar.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"fell","pos":"verb","ipa":"/fɛl/","gloss":"caiu"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"cousin","pos":"noun","ipa":"/ˈkʌzən/","gloss":"primo, prima"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-20-05', 'lesson-phrasal-b1-20', 5, 'phrasal', 'They made up the next day.', 'Eles fizeram as pazes no dia seguinte.', '/ðeɪ meɪd ʌp ðə nɛkst deɪ/', '"Make up" = fazer as pazes.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"made","pos":"verb","ipa":"/meɪd/","gloss":"fez, feito"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"next","pos":"adjective","ipa":"/nɛkst/","gloss":"próximo"},{"surface":"day","pos":"noun","ipa":"/deɪ/","gloss":"dia"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-20-06', 'lesson-phrasal-b1-20', 6, 'phrasal', 'I look up to my mother.', 'Admiro minha mãe.', '/aɪ lʊk ʌp tuː maɪ ˈmʌðər/', '"Look up to" = admirar.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"look","pos":"noun","ipa":"/lʊk/","gloss":"olhada"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"mother","pos":"noun","ipa":"/ˈmʌðər/","gloss":"mãe"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-20-07', 'lesson-phrasal-b1-20', 7, 'phrasal', 'Don''t let me down.', 'Não me decepcione.', '/doʊnt lɛt miː daʊn/', '"Let down" = decepcionar. Separável.', '[]'::jsonb, '[{"surface":"Don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"let","pos":"verb","ipa":"/lɛt/","gloss":"deixar, permitir"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"down","pos":"adjective","ipa":"/daʊn/","gloss":"dentro, topando (gíria)"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-20-08', 'lesson-phrasal-b1-20', 8, 'phrasal', 'She stood me up.', 'Ela me deu um bolo.', '/ʃiː stʊd miː ʌp/', '"Stand up" + pessoa = não aparecer no encontro.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"stood","pos":"verb","ipa":"/stʊd/","gloss":"ficou de pé"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-20-09', 'lesson-phrasal-b1-20', 9, 'phrasal', 'We grew apart over the years.', 'A gente se afastou com os anos.', '/wiː ɡruː əˈpɑːrt ˈoʊvər ðə jɪrz/', '"Grow apart" = afastar-se aos poucos.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"grew","pos":"verb","ipa":"/ɡruː/","gloss":"cresceu"},{"surface":"apart","pos":"adverb","ipa":"/əˈpɑːrt/","gloss":"separado, à parte"},{"surface":"over","pos":"preposition","ipa":"/ˈoʊvər/","gloss":"por cima; superado"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"years","pos":"noun","ipa":"/jɪrz/","gloss":"anos"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-20-10', 'lesson-phrasal-b1-20', 10, 'phrasal', 'I''ll catch up with you later.', 'Te encontro mais tarde para colocar o papo em dia.', '/aɪl kætʃ ʌp wɪð juː ˈleɪtər/', '"Catch up" = pôr a conversa em dia.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"catch","pos":"verb","ipa":"/kætʃ/","gloss":"pegar, apanhar"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"later","pos":"adverb","ipa":"/ˈleɪtər/","gloss":"mais tarde"}]'::jsonb, NULL, NULL)
